            { id: 'layer-1', name: 'Background Gradient', type: 'image', visible: true, locked: false }
        ]
    };

    let state = loadState();

    function loadState() {
        try {
            const raw = localStorage.getItem(STORAGE_KEY);
            if (raw) {
                const parsed = JSON.parse(raw);
                return { ...defaultState, ...parsed };
            }
