/* 
  Create Canvas — Interactive Behavior & Controller
*/

document.addEventListener('DOMContentLoaded', () => {
    console.log("Create Canvas Studio initialized successfully.");

    // Tool switching
    const toolBtns = document.querySelectorAll('.tool-btn');
    toolBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            toolBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            showToast(`Switched to ${btn.title.split(' ')[0]} tool`);
        });
    });

    // Sidebar Tab Switching
    const sidebarTabs = document.querySelectorAll('.sidebar-tab');
    const tabLayers = document.getElementById('tab-layers');
    const tabAssets = document.getElementById('tab-assets');
    const tabTemplates = document.getElementById('tab-templates');

    sidebarTabs.forEach(tab => {
        tab.addEventListener('click', () => {
            sidebarTabs.forEach(t => {
                t.classList.remove('text-blue-400', 'border-b-2', 'border-blue-500', 'bg-slate-900/40');
                t.classList.add('text-slate-400');
            });
            tab.classList.remove('text-slate-400');
            tab.classList.add('text-blue-400', 'border-b-2', 'border-blue-500', 'bg-slate-900/40');

            const tabName = tab.getAttribute('data-tab');
            tabLayers.classList.add('hidden');
            tabAssets.classList.add('hidden');
            tabTemplates.classList.add('hidden');

            if (tabName === 'layers') tabLayers.classList.remove('hidden');
            if (tabName === 'assets') tabAssets.classList.remove('hidden');
            if (tabName === 'templates') tabTemplates.classList.remove('hidden');
        });
    });

    // Modals Handling (Export & Share)
    const exportModal = document.getElementById('export-modal');
    const exportTrigger = document.getElementById('export-modal-trigger');
    const exportClose = document.getElementById('export-modal-close');
    const exportCancel = document.getElementById('export-cancel');
    const exportConfirm = document.getElementById('export-confirm');

    const shareModal = document.getElementById('share-modal');
    const shareTrigger = document.getElementById('share-modal-trigger');
    const shareClose = document.getElementById('share-modal-close');
    const shareDone = document.getElementById('share-done');
    const copyLinkBtn = document.getElementById('copy-link-btn');

    function openModal(modal) {
        modal.classList.remove('hidden');
        setTimeout(() => {
            modal.classList.add('modal-show');
        }, 10);
    }

    function closeModal(modal) {
        modal.classList.remove('modal-show');
        setTimeout(() => {
            modal.classList.add('hidden');
        }, 300);
    }

    exportTrigger.addEventListener('click', () => openModal(exportModal));
    exportClose.addEventListener('click', () => closeModal(exportModal));
    exportCancel.addEventListener('click', () => closeModal(exportModal));
    exportConfirm.addEventListener('click', () => {
        closeModal(exportModal);
        showToast("Canvas exported successfully as PNG!");
    });

    shareTrigger.addEventListener('click', () => openModal(shareModal));
    shareClose.addEventListener('click', () => closeModal(shareModal));
    shareDone.addEventListener('click', () => closeModal(shareModal));

    copyLinkBtn.addEventListener('click', () => {
        navigator.clipboard.writeText("https://createcanvas.app/share/v2_masterpiece_9948");
        copyLinkBtn.textContent = "Copied!";
        copyLinkBtn.classList.add('bg-emerald-600');
        setTimeout(() => {
            copyLinkBtn.textContent = "Copy";
            copyLinkBtn.classList.remove('bg-emerald-600');
        }, 2000);
        showToast("Secure share link copied to clipboard!");
    });

    // Zoom controls
    let currentZoom = 100;
    const zoomLevelEl = document.getElementById('zoom-level');
    const createCanvasEl = document.getElementById('create-canvas');
    const zoomInBtn = document.getElementById('zoom-in');
    const zoomOutBtn = document.getElementById('zoom-out');
    const zoomResetBtn = document.getElementById('zoom-reset');

    function updateZoom() {
        zoomLevelEl.textContent = `${currentZoom}%`;
        createCanvasEl.style.transform = `scale(${currentZoom / 100})`.trim();
    }

    zoomInBtn.addEventListener('click', () => {
        if (currentZoom < 200) {
            currentZoom += 10;
            updateZoom();
        }
    });

    zoomOutBtn.addEventListener('click', () => {
        if (currentZoom > 40) {
            currentZoom -= 10;
            updateZoom();
        }
    });

    zoomResetBtn.addEventListener('click', () => {
        currentZoom = 100;
        updateZoom();
        showToast("Zoom reset to 100%");
    });

    // Property Inspector binding
    const propWidth = document.getElementById('prop-width');
    const propHeight = document.getElementById('prop-height');
    const propRadius = document.getElementById('prop-radius');
    const radiusVal = document.getElementById('radius-val');

    propWidth.addEventListener('input', (e) => {
        if (e.target.value > 200 && e.target.value < 3000) {
            createCanvasEl.style.width = `${e.target.value}px`;
        }
    });

    propHeight.addEventListener('input', (e) => {
        if (e.target.value > 200 && e.target.value < 2000) {
            createCanvasEl.style.height = `${e.target.value}px`;
        }
    });

    propRadius.addEventListener('input', (e) => {
        const val = e.target.value;
        radiusVal.textContent = `${val}px`;
        createCanvasEl.style.borderRadius = `${val}px`;
    });

    // Toast Notification System
    function showToast(message) {
        const container = document.getElementById('toast-container');
        const toast = document.createElement('div');
        toast.className = 'bg-slate-900 border border-canvas-border text-slate-100 text-xs px-4 py-3 rounded-xl shadow-2xl flex items-center space-x-3 transform translate-y-4 opacity-0 transition-all duration-300 pointer-events-auto';
        toast.innerHTML = `
            <i class="fa-solid fa-circle-check text-blue-400"></i>
            <span>${message}</span>
        `;
        container.appendChild(toast);

        setTimeout(() => {
            toast.classList.remove('translate-y-4', 'opacity-0');
        }, 10);

        setTimeout(() => {
            toast.classList.add('translate-y-4', 'opacity-0');
            setTimeout(() => toast.remove(), 300);
        }, 3000);
    }

    // Asset Thumbnail Insertion
    const assetThumbs = document.querySelectorAll('.asset-thumb');
    assetThumbs.forEach(thumb => {
        thumb.addEventListener('click', () => {
            createCanvasEl.style.backgroundImage = `url(${thumb.src})`;
            createCanvasEl.style.backgroundSize = 'cover';
            createCanvasEl.style.backgroundPosition = 'center';
            showToast("Applied asset to canvas background!");
        });
    });

    // Undo / Redo mock
    document.getElementById('undo-btn').addEventListener('click', () => showToast("Undo last action"));
    document.getElementById('redo-btn').addEventListener('click', () => showToast("Redo last action"));
});

/* style.css — Create Canvas Chess Game Styling */

:root {
  --primary: #3c006b;
  --primary-light: #581c87;
  --accent: #00d06c;
  --accent-hover: #00b05b;
  --danger: #ef4444;
  --warning: #f59e0b;
  --bg-dark: #090d16;
  --bg-card: rgba(15, 23, 42, 0.75);
  --border-color: rgba(255, 255, 255, 0.12);
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --chessboard-light: #eeeed2;
  --chessboard-dark: #769656;
  --square-selected: rgba(255, 255, 0, 0.5);
  --square-highlight: rgba(0, 208, 108, 0.4);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.3), 0 10px 10px -5px rgba(0, 0, 0, 0.2);
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-dark);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow-x: hidden;
  background-image: 
    radial-gradient(circle at 10% 20%, rgba(60, 0, 107, 0.25) 0%, transparent 40%),
    radial-gradient(circle at 90% 80%, rgba(0, 208, 108, 0.15) 0%, transparent 40%);
  background-attachment: fixed;
}

/* Header & Navigation */
header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(9, 13, 22, 0.85);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 1rem 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.nav-brand h1 {
  font-size: 1.25rem;
  font-weight: 700;
  background: linear-gradient(135deg, #f8fafc, #94a3b8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

/* Main Layout */
main {
  flex: 1;
  max-width: 1400px;
  width: 100%;
  margin: 0 auto;
  padding: 2rem;
  display: grid;
  grid-template-columns: 1fr 380px;
  gap: 2rem;
  align-items: start;
}

@media (max-width: 1024px) {
  main {
    grid-template-columns: 1fr;
    padding: 1rem;
  }
}

/* Chessboard Section */
.canvas-container {
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  box-shadow: var(--shadow-lg);
}

.game-status-bar {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  padding: 0.75rem 1.25rem;
  background: rgba(255, 255, 255, 0.03);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

.player-info {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-weight: 600;
  font-size: 0.95rem;
}

.player-info.active {
  color: var(--accent);
}

.turn-badge {
  background: var(--primary);
  color: white;
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.85rem;
  font-weight: 500;
}

/* Chessboard Grid */
#chessboard, .chessboard {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  grid-template-rows: repeat(8, 1fr);
  width: min(520px, 80vw);
  height: min(520px, 80vw);
  border: 4px solid #1e293b;
  border-radius: var(--radius-sm);
  box-shadow: 0 10px 25px rgba(0,0,0,0.5);
  position: relative;
  overflow: hidden;
}

.square {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: min(45px, 8vw);
  cursor: pointer;
  user-select: none;
  transition: background-color 0.15s ease;
  position: relative;
}

.square.light {
  background-color: var(--chessboard-light);
  color: #2c2c2c;
}

.square.dark {
  background-color: var(--chessboard-dark);
  color: #2c2c2c;
}

.square:hover {
  filter: brightness(1.08);
}

.square.selected {
  background-color: var(--square-selected) !important;
}

.square.valid-move::after {
  content: '';
  position: absolute;
  width: 24%;
  height: 24%;
  background-color: rgba(0, 208, 108, 0.7);
  border-radius: 50%;
  pointer-events: none;
}

.square.valid-capture::after {
  content: '';
  position: absolute;
  inset: 4px;
  border: 4px solid rgba(239, 68, 68, 0.7);
  border-radius: 50%;
  pointer-events: none;
}

.piece {
  display: inline-block;
  cursor: grab;
  transition: transform 0.1s ease;
}

.piece:active {
  cursor: grabbing;
}

/* Sidebar / Controls */
.sidebar {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.panel {
  background: var(--bg-card);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  box-shadow: var(--shadow-lg);
}

.panel h3 {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text-main);
